-- GATE PACK 0256 overloads (POST-APPLY read-back). Read-only catalog SELECT, no writes, no table data. Generated by gate-packs/mkpacks.py; do not edit by hand.
select p.proname || '.overloads' as k, count(*)::text as v
from pg_catalog.pg_proc p
where p.pronamespace = 'public'::pg_catalog.regnamespace and p.proname in ('create_public_appointment_for_new_client', 'create_public_appointment_for_new_client_v2')
group by p.proname
order by 1;
